function validate([nums]) {
  if (nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 3 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -2147483648 || v > 2147483647)) return 'Each value must be a 32-bit signed integer.';
  const counts = new Map();
  for (const v of nums) counts.set(v, (counts.get(v) || 0) + 1);
  let singles = 0;
  for (const count of counts.values()) {
    if (count === 1) singles++;
    else if (count !== 3) return 'Every value except one must appear exactly three times.';
  }
  if (singles !== 1) return 'Exactly one value must appear only once.';
  return null;
}

